/* AMS Classical Notes (10pt, A4, Latin Modern, Small-Caps Centered Sections, Borderless amsthm) /
:root {
    --bg: #e5e7eb;
    --surface: #ffffff;
    --ink: #111827;
    --ink-muted: #374151;
    --ink-subtle: #6b7280;
    --link-blue: #0000ee;
    --border: #d1d5db;
    --border-strong: #111827;
    --font-serif: 'Latin Modern Roman', 'CMU Serif', 'Computer Modern', Georgia, serif;
    --font-sans: 'Latin Modern Roman', 'CMU Serif', Georgia, serif;
    --font-code: 'Fira Code', 'JetBrains Mono', monospace;
}

 { box-sizing: border-box; }

html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    background-color: var(--bg);
    color: var(--ink);
    font-family: var(--font-serif);
    font-size: 14.5px;
    line-height: 1.52;
    -webkit-font-smoothing: antialiased;
}

body {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 28px 16px;
}

/* A4 Sheet with 2.5cm equivalent margins /
.article-wrapper {
    width: 100%;
    max-width: 794px;
    background: var(--surface);
    padding: 64px 72px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.12);
    border: 1px solid #cbd5e1;
    font-family: var(--font-serif);
    font-size: 14.5px;
    line-height: 1.52;
}

/ Running Header mimicking fancyhdr (left page/tag, right small-caps title) /
.top-nav {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding-bottom: 14px;
    margin-bottom: 10px;
    border-bottom: none;
    font-family: var(--font-serif);
    font-size: 12px;
    color: var(--ink);
}

.back-home {
    font-size: 12px;
    font-weight: 400;
    color: var(--ink);
    text-decoration: none;
    text-transform: none;
    letter-spacing: 0;
}

.nav-tag {
    font-size: 11.5px;
    font-weight: 400;
    font-variant: small-caps;
    letter-spacing: 0.05em;
    color: var(--ink);
    background: transparent;
    border: none;
    padding: 0;
}

/ Centered Small-Caps Title & Stacked Metadata /
.article-header {
    text-align: center;
    border-bottom: none;
    padding-top: 4px;
    padding-bottom: 10px;
    margin-bottom: 14px;
}

.header-main-group {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
}

.post-title {
    font-family: var(--font-serif);
    font-size: 21px;
    font-weight: 400;
    font-variant: small-caps;
    letter-spacing: 0.06em;
    color: var(--ink);
    margin: 0;
    line-height: 1.3;
}

.subtitle {
    font-family: var(--font-serif);
    font-size: 14.5px;
    font-weight: 400;
    font-style: normal;
    color: var(--ink);
    margin: 0;
}

.post-meta {
    font-family: var(--font-serif);
    font-size: 14px;
    color: var(--ink);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    margin-top: 2px;
}

/ Compact Classical LaTeX Abstract (\small with narrower margins) /
.abstract-box {
    border: none;
    background: transparent;
    box-shadow: none;
    margin: 8px 46px 24px 46px;
    padding: 0;
    font-size: 13px;
    line-height: 1.48;
    text-align: justify;
}

.abstract-label {
    font-family: var(--font-serif);
    font-size: 13px;
    font-weight: 700;
    font-variant: small-caps;
    letter-spacing: 0.04em;
    color: var(--ink);
    text-transform: none;
    display: block;
    text-align: center;
    margin-bottom: 4px;
}

.abstract-text {
    font-style: normal;
    color: var(--ink);
    font-size: 13px;
    margin: 0;
}

/ Body Typography: Justified, 1.5em paragraph indent, 0pt parskip /
.article-content {
    text-align: justify;
    color: var(--ink);
}

.article-content p {
    margin: 0;
    text-indent: 1.5em;
}

.article-content h2 + p,
.article-content h3 + p,
.article-content .abstract-box + p,
.article-content .clawri-thm + p,
.article-content .clawri-proof + p,
.article-content .math-block + p,
.article-content figure + p,
.article-content blockquote + p {
    text-indent: 0;
}

/ Centered Small-Caps Section Headings (titlesec) /
.article-content h2 {
    font-family: var(--font-serif);
    font-size: 16px;
    font-weight: 400;
    font-variant: small-caps;
    letter-spacing: 0.06em;
    text-align: center;
    color: var(--ink);
    border-bottom: none;
    padding-bottom: 0;
    margin: 28px 0 14px 0;
}

.article-content h3 {
    font-family: var(--font-serif);
    font-size: 14.5px;
    font-weight: 700;
    text-align: left;
    color: var(--ink);
    margin: 20px 0 8px 0;
}

/ Hyperref Blue Links /
.article-content a,
.clawri-cite a,
sup.fn-ref a {
    color: var(--link-blue) !important;
    text-decoration: none;
}

.article-content a:hover {
    text-decoration: underline;
}

/ Pure Borderless amsthm Environments /
.clawri-thm {
    border: none !important;
    background: transparent !important;
    padding: 0 !important;
    margin: 14px 0 !important;
    border-radius: 0 !important;
}

.clawri-thm-title {
    display: inline;
    font-family: var(--font-serif);
    font-weight: 700;
    font-style: normal;
    color: var(--ink);
    margin-right: 0.45em;
}

.clawri-thm-title::after {
    content:

;
}

.clawri-thm-body {
    display: inline;
}

/ theoremstyle{plain}: Italic body /
.clawri-theorem .clawri-thm-body,
.clawri-lemma .clawri-thm-body,
.clawri-proposition .clawri-thm-body,
.clawri-corollary .clawri-thm-body {
    font-style: italic;
}

/ theoremstyle{definition}: Upright body /
.clawri-definition .clawri-thm-body,
.clawri-exercise .clawri-thm-body {
    font-style: normal;
}

/ theoremstyle{remark}: Italic title, upright body /
.clawri-remark .clawri-thm-title {
    font-weight: 400;
    font-style: italic;
}
.clawri-remark .clawri-thm-body {
    font-style: normal;
}

/ Proof environment /
.clawri-proof {
    padding-left: 0 !important;
    margin: 12px 0 16px 0 !important;
}

.clawri-proof > em:first-child {
    font-style: italic;
}

/ Minimal Callout Boxes & Quotes /
.clawri-box {
    border: none !important;
    border-left: 2px solid var(--ink) !important;
    background: transparent !important;
    color: var(--ink) !important;
    padding: 4px 0 4px 14px !important;
    margin: 16px 0 !important;
    border-radius: 0 !important;
}

blockquote.quote-box {
    margin: 18px 28px;
    padding: 0;
    border: none;
    background: transparent;
    font-size: 13.5px;
    color: var(--ink);
}

blockquote.quote-box p {
    text-indent: 0;
    font-style: normal;
}

blockquote.quote-box cite {
    display: block;
    text-align: right;
    font-size: 12.5px;
    color: var(--ink-muted);
    margin-top: 4px;
}

/ Classical LaTeX Bottom Footnote Rule */
.section-title-box {
    font-family: var(--font-serif);
    font-size: 15px;
    font-weight: 400;
    font-variant: small-caps;
    letter-spacing: 0.06em;
    text-align: center;
    color: var(--ink);
    border-bottom: none;
    margin-top: 30px;
    margin-bottom: 12px;
}

.footnotes {
    margin-top: 32px;
    padding-top: 8px;
    position: relative;
    font-size: 12.5px;
    line-height: 1.45;
}

.footnotes::before {
    content:

;
    display: block;
    width: 36%;
    border-top: 0.8px solid var(--ink);
    margin-bottom: 8px;
}

.footnotes .section-title-box {
    display: none;
}

.footnotes ol {
    padding-left: 18px;
    margin: 0;
}

.sidenote-desktop { display: none !important; }
.article-footer { display: none; }

@page {
    size: A4;
    margin: 25mm;
}

@media print {
    body {
        background: #ffffff;
        padding: 0;
    }
    .article-wrapper {
        box-shadow: none;
        border: none;
        padding: 0;
        max-width: 100%;
    }
    .clawri-pdf-btn-wrap,
    .fn-overlay {
        display: none !important;
    }
}
